Json::Value OrganizationService::listPendingInvitationsForUser(const std::string &actorUserId) const
{
    const auto actor = userRepository_.findUserById(actorUserId);
    if (actor.isNull())
    {
        throw common::AppException("USER_NOT_FOUND", "User not found: " + actorUserId, drogon::k404NotFound);
    }

    std::vector<Json::Value> visibleInvitations;
    const auto organizations = organizationRepository_.allOrganizationsArray();
    for (const auto &organizationValue : organizations)
    {
        const auto organizationId = organizationValue.get("organization_id", organizationValue.get("scope_id", "")).asString();
        if (organizationId.empty())
        {
            continue;
        }
        const auto organization = requireOrganization(organizationId);
        for (const auto &invitation : organization.get("invitations", Json::Value(Json::arrayValue)))
        {
            const auto invitationView = buildPendingInvitationView(actor, organization, invitation);
            if (!invitationView.isNull())
            {
                visibleInvitations.push_back(invitationView);
            }
        }
    }

    std::sort(visibleInvitations.begin(), visibleInvitations.end(), [](const Json::Value &left, const Json::Value &right) {
        const auto leftCanAccept = left.get("can_accept", false).asBool();
        const auto rightCanAccept = right.get("can_accept", false).asBool();
        if (leftCanAccept != rightCanAccept)
        {
            return leftCanAccept > rightCanAccept;
        }
        return left.get("created_at", "").asString() > right.get("created_at", "").asString();
    });

    Json::Value out(Json::arrayValue);
    for (const auto &entry : visibleInvitations)
    {
        out.append(entry);
    }
    return out;
}

Json::Value OrganizationService::upsertMember(const std::string &actorUserId, const std::string &organizationId, const Json::Value &payload)
{
    const auto organization = requireOrganization(organizationId);
    const auto userId = payload.get("user_id", "").asString();
    if (userId.empty())
    {
        throw common::AppException("VALIDATION_ERROR", "Missing field: user_id", drogon::k422UnprocessableEntity);
    }

    const auto user = userRepository_.findUserById(userId);
    if (user.isNull())
    {
        throw common::AppException("USER_NOT_FOUND", "User not found: " + userId, drogon::k404NotFound);
    }

    const auto existing = organizationRepository_.findMembership(userId, organizationId);
    const auto subscription = subscriptionService_.subscriptionForOrganization(organizationId);
    const auto seats = subscription.get("seats", 0).asInt();
    if (existing.isNull() && seats > 0 && organizationRepository_.memberCount(organizationId) >= seats)
    {
        throw common::AppException("ORGANIZATION_SEATS_FULL", "Organization seat limit reached", drogon::k409Conflict);
    }

    const auto roles = normalizeMemberRoles(payload.isMember("roles") ? payload["roles"] : defaultMemberRoles());
    ensureOrgAdminGuard(organizationId, existing, roles);
    const auto permissionTemplates = payload.isMember("permission_templates")
                                         ? normalizePermissionTemplates(payload["permission_templates"], roles)
                                         : normalizePermissionTemplates(existing.get("permission_templates", Json::Value(Json::arrayValue)), roles);
    const auto permissionOverrides = payload.isMember("permission_overrides")
                                         ? normalizePermissionOverrides(payload["permission_overrides"])
                                         : normalizePermissionOverrides(existing.get("permission_overrides", Json::Value(Json::arrayValue)));

    Json::Value membership(Json::objectValue);
    membership["membership_id"] = existing.isNull() ? Json::Value(Json::nullValue) : existing.get("membership_id", "");
    membership["user_id"] = userId;
    membership["scope_type"] = "organization";
    membership["scope_id"] = organizationId;
    membership["organization_type"] = organization.get("organization_type", "business").asString();
    membership["roles"] = roles;
    membership["permission_templates"] = permissionTemplates;
    membership["permission_overrides"] = permissionOverrides;
    membership["joined_at"] = existing.isNull() ? common::nowIso8601() : existing.get("joined_at", common::nowIso8601()).asString();
    membership["member_no"] = payload.get("member_no", existing.get("member_no", "")).asString();
    membership["student_no"] = payload.get("student_no", existing.get("student_no", "")).asString();
    membership["employee_no"] = payload.get("employee_no", existing.get("employee_no", "")).asString();
    membership = assignBusinessNumbers(organization, membership, existing);

    auto savedMembership = organizationRepository_.upsertMembership(membership);
    auto savedOrganization = requireOrganization(organizationId);
    savedOrganization = appendAuditEntry(
        savedOrganization,
        createAuditEntry(
            actorUserId,
            existing.isNull() ? "member.added" : "member.updated",
            existing.isNull() ? "添加组织成员" : "更新组织成员",
            [&] {
                Json::Value details(Json::objectValue);
                details["user_id"] = userId;
                details["username"] = user.get("username", "").asString();
                details["roles"] = roles;
                details["permission_templates"] = permissionTemplates;
                details["permission_overrides"] = permissionOverrides;
                details["member_no"] = savedMembership.get("member_no", "").asString();
                if (!existing.isNull())
                {
                    details["previous_roles"] = existing["roles"];
                    details["previous_permission_templates"] = existing.get("permission_templates", Json::Value(Json::arrayValue));
                    details["previous_permission_overrides"] = existing.get("permission_overrides", Json::Value(Json::arrayValue));
                    details["previous_member_no"] = existing.get("member_no", "").asString();
                }
                return details;
            }()));
    organizationRepository_.upsertOrganization(savedOrganization);

    return enrichMembership(savedMembership);
}

void OrganizationService::removeMember(const std::string &actorUserId, const std::string &organizationId, const std::string &userId)
{
    auto organization = requireOrganization(organizationId);
    const auto existing = organizationRepository_.findMembership(userId, organizationId);
    if (existing.isNull())
    {
        return;
    }
    ensureOrgAdminGuard(organizationId, existing, Json::Value(Json::nullValue));
    const auto user = userRepository_.findUserById(userId);
    organizationRepository_.removeMembership(userId, organizationId);
    organization = appendAuditEntry(
        organization,
        createAuditEntry(
            actorUserId,
            "member.removed",
            "移除组织成员",
            [&] {
                Json::Value details(Json::objectValue);
                details["user_id"] = userId;
                details["username"] = user.isNull() ? std::string("") : user.get("username", "").asString();
                details["roles"] = existing["roles"];
                details["member_no"] = existing.get("member_no", "").asString();
                return details;
            }()));
    organizationRepository_.upsertOrganization(organization);
}

Json::Value OrganizationService::listOrganizationSummaries(const std::string &userId, bool includeAll,
                                                            const std::string &query, int page, int pageSize) const
{
    const auto organizations = includeAll ? organizationRepository_.allOrganizationsArray()
                                          : organizationRepository_.listOrganizationsForUser(userId);
    const auto counts = organizationRepository_.memberCounts();
    std::vector<Json::Value> matches;
    std::string normalizedQuery = query;
    std::transform(normalizedQuery.begin(), normalizedQuery.end(), normalizedQuery.begin(),
                   [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    for (const auto &organization : organizations)
    {
        const auto id = organization.get("organization_id", organization.get("scope_id", "")).asString();
        const auto name = organization.get("name", "").asString();
        std::string searchable = id + " " + name;
        std::transform(searchable.begin(), searchable.end(), searchable.begin(),
                       [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
        if (!normalizedQuery.empty() && searchable.find(normalizedQuery) == std::string::npos) continue;
        Json::Value summary(Json::objectValue);
        summary["organization_id"] = id;
        summary["name"] = name;
        summary["organization_type"] = organization.get("organization_type", "business").asString();
        summary["status"] = organization.get("status", "active").asString();
        summary["subscription"] = organization.get("subscription", Json::Value(Json::objectValue));
        summary["member_count"] = counts.contains(id) ? counts.at(id) : 0;
        matches.push_back(std::move(summary));
    }
    std::stable_sort(matches.begin(), matches.end(), [](const Json::Value &a, const Json::Value &b) {
        return a.get("name", "").asString() < b.get("name", "").asString();
    });
    Json::Value out(Json::objectValue);
    out["items"] = Json::arrayValue;
    const int total = static_cast<int>(matches.size());
    const int begin = (page - 1) * pageSize;
    for (int i = begin; i < total && i < begin + pageSize; ++i) out["items"].append(matches[static_cast<std::size_t>(i)]);
    out["total"] = total;
    out["page"] = page;
    out["page_size"] = pageSize;
    out["pages"] = total == 0 ? 0 : (total + pageSize - 1) / pageSize;
    return out;
}

Json::Value OrganizationService::updateRolePermissions(const std::string &actorUserId,
                                                       const std::string &organizationId,
                                                       const std::string &roleId,
                                                       const Json::Value &payload)
{
    auto organization = requireOrganization(organizationId);
    std::unordered_set<std::string> allowedRoles;
    for (const auto &role : allowedRolePermissionRoles())
    {
        allowedRoles.insert(role.asString());
    }
    if (!allowedRoles.contains(roleId))
    {
        throw common::AppException("VALIDATION_ERROR", "Unsupported role for organization permissions", drogon::k422UnprocessableEntity);
    }

    const auto before = normalizeRolePermissions(organization.get("role_permissions", Json::Value(Json::objectValue)));
    Json::Value next = before;
    Json::Value config(Json::objectValue);
    config["allow"] = normalizePermissionIdArray(payload.get("allow", Json::Value(Json::arrayValue)));
    config["deny"] = normalizePermissionIdArray(payload.get("deny", Json::Value(Json::arrayValue)));

    std::unordered_set<std::string> denySet;
    for (const auto &permission : config["deny"])
    {
        denySet.insert(permission.asString());
    }
    Json::Value cleanAllow(Json::arrayValue);
    for (const auto &permission : config["allow"])
    {
        if (!denySet.contains(permission.asString()))
        {
            cleanAllow.append(permission.asString());
        }
    }
    config["allow"] = cleanAllow;
    next[roleId] = config;

    organization["role_permissions"] = normalizeRolePermissions(next);
    organization = appendAuditEntry(
        organization,
        createAuditEntry(
            actorUserId,
            "role_permissions.updated",
            "更新机构角色权限",
            [&] {
                Json::Value details(Json::objectValue);
                details["role"] = roleId;
                details["allow"] = config["allow"];
                details["deny"] = config["deny"];
                details["previous"] = before.get(roleId, Json::Value(Json::objectValue));
                return details;
            }()));
    return enrichOrganization(organizationRepository_.upsertOrganization(organization));
}

Json::Value OrganizationService::updateSubscription(const std::string &actorUserId, const std::string &organizationId, const Json::Value &patch)
{
    const auto before = subscriptionService_.subscriptionForOrganization(organizationId);
    const auto updated = subscriptionService_.updateOrganizationSubscription(organizationId, patch);
    auto organization = requireOrganization(organizationId);
    organization = appendAuditEntry(
        organization,
        createAuditEntry(
            actorUserId,
            "subscription.updated",
            "更新组织套餐与席位",
            [&] {
                Json::Value details(Json::objectValue);
                details["previous_plan"] = before.get("plan", "free").asString();
                details["plan"] = updated.get("plan", "free").asString();
                details["previous_status"] = before.get("status", "active").asString();
                details["status"] = updated.get("status", "active").asString();
                details["previous_seats"] = before.get("seats", 0).asInt();
                details["seats"] = updated.get("seats", 0).asInt();
                details["previous_expires_at"] = before.get("expires_at", "").asString();
                details["expires_at"] = updated.get("expires_at", "").asString();
                return details;
            }()));
    organizationRepository_.upsertOrganization(organization);
    return updated;
}

