Json::Value OrganizationService::upsertCoursePackage(const std::string &actorUserId, const std::string &organizationId, const Json::Value &payload)
{
    auto organization = requireOrganization(organizationId);
    const auto packageId = payload.get("course_package_id", payload.get("id", "")).asString().empty()
                               ? common::generateOpaqueId("pkg_")
                               : payload.get("course_package_id", payload.get("id", "")).asString();
    const auto existing = findEntityById(ensureArray(organization.get("course_packages", Json::Value(Json::arrayValue))), "course_package_id", packageId);
    const auto studentId = payload.get("student_id", existing.get("student_id", "")).asString();
    if (studentId.empty())
    {
        throw common::AppException("VALIDATION_ERROR", "student_id is required", drogon::k422UnprocessableEntity);
    }
    if (userRepository_.findUserById(studentId).isNull())
    {
        throw common::AppException("USER_NOT_FOUND", "Student not found: " + studentId, drogon::k404NotFound);
    }

    const auto totalLessons = (std::max)(0, payload.get("total_lessons", existing.get("total_lessons", 0)).asInt());
    const auto usedLessons = (std::max)(0, payload.get("used_lessons", existing.get("used_lessons", 0)).asInt());
    const auto remainingLessons = payload.isMember("remaining_lessons")
                                      ? (std::max)(0, payload.get("remaining_lessons", 0).asInt())
                                      : (std::max)(0, totalLessons - usedLessons);
    Json::Value coursePackage(Json::objectValue);
    coursePackage["course_package_id"] = packageId;
    coursePackage["id"] = packageId;
    coursePackage["organization_id"] = organizationId;
    coursePackage["student_id"] = studentId;
    coursePackage["subject"] = payload.get("subject", existing.get("subject", "")).asString();
    coursePackage["title"] = payload.get("title", existing.get("title", "")).asString();
    coursePackage["total_lessons"] = totalLessons;
    coursePackage["remaining_lessons"] = remainingLessons;
    coursePackage["used_lessons"] = usedLessons;
    coursePackage["expires_at"] = payload.get("expires_at", existing.get("expires_at", "")).asString();
    coursePackage["status"] = normalizeCoursePackageStatus(payload.get("status", existing.get("status", "active")).asString());
    if (!existing.isNull())
    {
        coursePackage["created_at"] = existing.get("created_at", "").asString();
        coursePackage["created_by"] = existing.get("created_by", "").asString();
    }
    coursePackage = touchEntity(coursePackage, actorUserId, existing.isNull());

    organization["course_packages"] = replaceEntityById(ensureArray(organization.get("course_packages", Json::Value(Json::arrayValue))), "course_package_id", packageId, coursePackage);
    organization = appendAuditEntry(
        organization,
        createAuditEntry(
            actorUserId,
            existing.isNull() ? "course_package.created" : "course_package.updated",
            existing.isNull() ? "创建课程包" : "更新课程包",
            [&] {
                Json::Value details(Json::objectValue);
                details["course_package_id"] = packageId;
                details["student_id"] = studentId;
                details["subject"] = coursePackage.get("subject", "").asString();
                return details;
            }()));
    organizationRepository_.upsertOrganization(organization);
    return coursePackage;
}

bool OrganizationService::canAccessOrganization(const std::string &actorUserId, const Json::Value &actorRoles, const std::string &organizationId) const
{
    if (hasPlatformRole(actorRoles))
    {
        return true;
    }
    return !organizationRepository_.findMembership(actorUserId, organizationId).isNull();
}

bool OrganizationService::canManageOrganization(const std::string &actorUserId, const Json::Value &actorRoles, const std::string &organizationId) const
{
    if (hasPlatformRole(actorRoles))
    {
        return true;
    }

    const auto membership = organizationRepository_.findMembership(actorUserId, organizationId);
    if (membership.isNull())
    {
        return false;
    }

    for (const auto &role : membership["roles"])
    {
        if (role.asString() == "orgAdmin")
        {
            return true;
        }
    }
    return false;
}

Json::Value OrganizationService::requireOrganization(const std::string &organizationId) const
{
    const auto organization = organizationRepository_.findOrganization(organizationId);
    if (organization.isNull())
    {
        throw common::AppException("ORGANIZATION_NOT_FOUND", "Organization not found: " + organizationId, drogon::k404NotFound);
    }
    return organization;
}

Json::Value OrganizationService::enrichOrganization(Json::Value organization) const
{
    const auto organizationId = organization.get("organization_id", organization.get("scope_id", "")).asString();
    organization["member_count"] = organizationRepository_.memberCount(organizationId);
    organization["subscription"] = subscriptionService_.subscriptionForOrganization(organizationId);
    organization["seats"] = organization["subscription"].get("seats", 0).asInt();
    if (!organization.isMember("invitations") || !organization["invitations"].isArray())
    {
        organization["invitations"] = Json::arrayValue;
    }
    if (!organization.isMember("audit_logs") || !organization["audit_logs"].isArray())
    {
        organization["audit_logs"] = Json::arrayValue;
    }
    organization["role_permissions"] = normalizeRolePermissions(organization.get("role_permissions", Json::Value(Json::objectValue)));
    return organization;
}

Json::Value OrganizationService::enrichMembership(Json::Value membership) const
{
    const auto user = userRepository_.findUserById(membership.get("user_id", "").asString());
    if (!user.isNull())
    {
        membership["username"] = user.get("username", "").asString();
        membership["status"] = user.get("status", "active").asString();
    }

    const auto organization = organizationRepository_.findOrganization(membership.get("scope_id", "").asString());
    if (!organization.isNull())
    {
        membership["organization_id"] = organization.get("organization_id", "").asString();
        membership["organization_name"] = organization.get("name", "").asString();
    }
    if (!membership.isMember("permission_overrides") || !membership["permission_overrides"].isArray())
    {
        membership["permission_overrides"] = Json::arrayValue;
    }
    if (!membership.isMember("permission_templates") || !membership["permission_templates"].isArray())
    {
        membership["permission_templates"] = Json::arrayValue;
    }
    return membership;
}

Json::Value OrganizationService::assignBusinessNumbers(const Json::Value &organization, Json::Value membership, const Json::Value &existing) const
{
    const auto organizationId = organization.get("organization_id", "").asString();
    const auto organizationType = organization.get("organization_type", "business").asString();

    auto memberNo = membership.get("member_no", existing.get("member_no", "")).asString();
    auto studentNo = membership.get("student_no", existing.get("student_no", "")).asString();
    auto employeeNo = membership.get("employee_no", existing.get("employee_no", "")).asString();

    if (memberNo.empty())
    {
        memberNo = !studentNo.empty() ? studentNo : employeeNo;
    }
    if (memberNo.empty())
    {
        memberNo = nextOrganizationMemberNo(organizationId, organizationType);
    }

    membership["member_no"] = memberNo;
    if (organizationType == "school")
    {
        membership["student_no"] = studentNo.empty() ? memberNo : studentNo;
        membership["employee_no"] = "";
    }
    else
    {
        membership["employee_no"] = employeeNo.empty() ? memberNo : employeeNo;
        membership["student_no"] = "";
    }
    return membership;
}

std::string OrganizationService::nextOrganizationMemberNo(const std::string &organizationId, const std::string &organizationType) const
{
    const auto memberships = organizationRepository_.listMembershipsForScope(organizationId);
    int maxSerial = 0;
    const auto prefix = organizationType == "school" ? std::string("STU-") : std::string("EMP-");
    for (const auto &membership : memberships)
    {
        maxSerial = (std::max)(maxSerial, extractPrefixedSerial(membership.get("member_no", "").asString(), prefix));
        maxSerial = (std::max)(maxSerial, extractPrefixedSerial(membership.get("student_no", "").asString(), prefix));
        maxSerial = (std::max)(maxSerial, extractPrefixedSerial(membership.get("employee_no", "").asString(), prefix));
    }
    return prefix + padSerial(maxSerial + 1, 6);
}

int OrganizationService::extractPrefixedSerial(const std::string &value, const std::string &prefix)
{
    if (value.rfind(prefix, 0) != 0)
    {
        return 0;
    }
    const auto serial = value.substr(prefix.size());
    if (serial.empty())
    {
        return 0;
    }
    for (const auto ch : serial)
    {
        if (ch < '0' || ch > '9')
        {
            return 0;
        }
    }
    return std::stoi(serial);
}

std::string OrganizationService::padSerial(int value, int width)
{
    auto text = std::to_string(value);
    if (static_cast<int>(text.size()) >= width)
    {
        return text;
    }
    return std::string(static_cast<size_t>(width - text.size()), '0') + text;
}

std::string OrganizationService::normalizeOrganizationType(const std::string &organizationType)
{
    if (organizationType == "business" || organizationType == "school")
    {
        return organizationType;
    }
    return "";
}

std::string OrganizationService::normalizeLearningGroupType(const std::string &type)
{
    if (type == "booking")
    {
        return "booking";
    }
    return "class";
}

std::string OrganizationService::normalizeLearningGroupStatus(const std::string &status)
{
    if (status == "finished")
    {
        return "completed";
    }
    if (status == "canceled")
    {
        return "cancelled";
    }
    if (status == "scheduled" || status == "active" || status == "completed" || status == "cancelled" ||
        status == "rescheduled" || status == "no_show" || status == "archived")
    {
        return status;
    }
    return "active";
}

std::string OrganizationService::normalizeEnrollmentRole(const std::string &role)
{
    if (role == "teacher" || role == "assistant")
    {
        return role;
    }
    return "student";
}

std::string OrganizationService::normalizeCoursePackageStatus(const std::string &status)
{
    if (status == "finished")
    {
        return "depleted";
    }
    if (status == "canceled")
    {
        return "cancelled";
    }
    if (status == "active" || status == "expired" || status == "paused" || status == "depleted" || status == "cancelled")
    {
        return status;
    }
    return "active";
}

